import{_ as a,c as e,o as l,a3 as r}from"./chunks/framework.Cc9k46oU.js";const g=JSON.parse('{"title":"デイリースクラム","description":"デイリースクラム（Daily Scrum）の効果的な進め方をステップごとに解説します。アジャイルチームの連携強化、進捗確認、障害の解消を目的とした15分間のミーティングの核心原則と実践のヒントを確認できます。","frontmatter":{"title":"デイリースクラム","description":"デイリースクラム（Daily Scrum）の効果的な進め方をステップごとに解説します。アジャイルチームの連携強化、進捗確認、障害の解消を目的とした15分間のミーティングの核心原則と実践のヒントを確認できます。","head":[["meta",{"name":"keywords","content":"デイリースクラム, Daily Scrum, スクラムミーティング, アジャイル, アジャイル開発手法, スクラムマスター, チームコラボレーション, 朝会, スクラムの進め方, アジャイルコーチング, チーム障害解消"}],["meta",{"property":"og:title","content":"デイリースクラム"}],["meta",{"property":"og:description","content":"デイリースクラム（Daily Scrum）の効果的な進め方をステップごとに解説します。アジャイルチームの連携強化、進捗確認、障害の解消を目的とした15分間のミーティングの核心原則と実践のヒントを確認できます。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/dailyScrum"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/dailyScrum"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"デイリースクラム | Empasy Docs"}],["meta",{"property":"og:description","content":"デイリースクラム（Daily Scrum）の効果的な進め方をステップごとに解説します。アジャイルチームの連携強化、進捗確認、障害の解消を目的とした15分間のミーティングの核心原則と実践のヒントを確認できます。"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/dailyScrum"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"デイリースクラム | Empasy Docs"}],["meta",{"name":"twitter:description","content":"デイリースクラム（Daily Scrum）の効果的な進め方をステップごとに解説します。アジャイルチームの連携強化、進捗確認、障害の解消を目的とした15分間のミーティングの核心原則と実践のヒントを確認できます。"}]],"sort":3000},"headers":[],"relativePath":"ja/agile/dailyScrum.md","filePath":"ja/agile/dailyScrum.md","lastUpdated":1795293539000}'),i={name:"ja/agile/dailyScrum.md"};function o(n,t,s,d,h,c){return l(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="デイリースクラムの進め方" tabindex="-1">デイリースクラムの進め方 <a class="header-anchor" href="#デイリースクラムの進め方" aria-label="Permalink to “デイリースクラムの進め方”">​</a></h1><ol><li><strong>時間と場所の固定</strong></li></ol><ul><li>毎日同じ時間（例：午前9時）に実施します。</li><li>同じ場所（会議室またはオンラインビデオ会議）に集まります。</li></ul><ol start="2"><li><strong>参加者</strong></li></ol><ul><li>開発チーム全員（開発者、QA など）</li><li>スクラムマスター（進行補助）、プロダクトオーナー（PO）はオブザーバーとして参加可能です。</li></ul><ol start="3"><li><strong>進行方式</strong></li></ol><ul><li><p>所要時間は <strong>15分以内</strong> に収めます。</p></li><li><p>チームメンバーが <strong>順番に共有</strong> します。</p></li><li><p><strong>3つの質問</strong> に沿って簡潔に報告します。</p><ol><li>昨日何を行いましたか？</li><li>今日何を行う予定ですか？</li><li>進行を妨げている障害（ブロッカー）はありますか？</li></ol></li></ul><ol start="4"><li><strong>重要原則</strong></li></ol><ul><li>詳細な技術説明ではなく「共有」を中心に行います。</li><li>障害の具体的な解決策は、スクラム終了後に別途議論します。</li><li>進捗報告ではなく、<strong>チーム間の同期（シンク）を目的</strong> とします。</li></ul><hr><h1 id="デイリースクラム-進行例スクリプト" tabindex="-1">デイリースクラム 進行例スクリプト <a class="header-anchor" href="#デイリースクラム-進行例スクリプト" aria-label="Permalink to “デイリースクラム 進行例スクリプト”">​</a></h1><h2 id="基本情報" tabindex="-1">基本情報 <a class="header-anchor" href="#基本情報" aria-label="Permalink to “基本情報”">​</a></h2><ul><li><strong>時間</strong>: 毎日 10:00（15分以内）</li><li><strong>参加者</strong>: 開発チーム全体、スクラムマスター、必要に応じてプロダクトオーナー（PO）</li><li><strong>形式</strong>: スタンドアップ形式（リモートの場合はビデオ会議）</li></ul><hr><h2 id="_1-開始の挨拶および会議目的の確認-2分" tabindex="-1">1. 開始の挨拶および会議目的の確認（2分） <a class="header-anchor" href="#_1-開始の挨拶および会議目的の確認-2分" aria-label="Permalink to “1. 開始の挨拶および会議目的の確認（2分）”">​</a></h2><p><strong>スクラムマスター</strong>:</p><blockquote><p>「おはようございます。デイリースクラムを開始します。本日も各自、昨日実施したこと、今日予定していること、そして障害となる要素があれば共有をお願いします。」</p></blockquote><hr><h2 id="_2-メンバーごとの進捗共有-10分" tabindex="-1">2. メンバーごとの進捗共有（10分） <a class="header-anchor" href="#_2-メンバーごとの進捗共有-10分" aria-label="Permalink to “2. メンバーごとの進捗共有（10分）”">​</a></h2><h3 id="佐藤-開発" tabindex="-1">佐藤（開発） <a class="header-anchor" href="#佐藤-開発" aria-label="Permalink to “佐藤（開発）”">​</a></h3><blockquote><p>「昨日はユーザーログイン API の開発を完了しました。本日はユーザープロフィール取得機能を実装する予定です。現在、特に障害となる要素はありません。」</p></blockquote><h3 id="鈴木-デザイン" tabindex="-1">鈴木（デザイン） <a class="header-anchor" href="#鈴木-デザイン" aria-label="Permalink to “鈴木（デザイン）”">​</a></h3><blockquote><p>「昨日は決済ページの UI デザインを完了し、開発チームへ引き渡しました。本日は管理画面のデザインに着手する予定です。ただし、開発パートと認識を合わせたい点があるため、午後に短いミーティングをお願いできますでしょうか？」</p></blockquote><p><strong>スクラムマスター</strong>:</p><blockquote><p>「承知しました。会議後に関係メンバー間で日程を調整します。」</p></blockquote><h3 id="高橋-バックエンド" tabindex="-1">高橋（バックエンド） <a class="header-anchor" href="#高橋-バックエンド" aria-label="Permalink to “高橋（バックエンド）”">​</a></h3><blockquote><p>「昨日は DB 最適化作業を進め、本日はパフォーマンステストを実施する予定です。ただし、テストサーバーの CPU 使用率が高いため、モニタリングが必要になりそうです。」</p></blockquote><p><strong>スクラムマスター</strong>:</p><blockquote><p>「障害要素として記録しておき、会議後にインフラチームと協議します。」</p></blockquote><h3 id="田中-qa" tabindex="-1">田中（QA） <a class="header-anchor" href="#田中-qa" aria-label="Permalink to “田中（QA）”">​</a></h3><blockquote><p>「昨日はログイン機能のテストを完了し、本日は新たに追加された決済機能のテストを開始する予定です。テストシナリオのうち、開発チームに確認したい箇所がいくつかあります。」</p></blockquote><p><strong>スクラムマスター</strong>:</p><blockquote><p>「会議後、すぐに担当の開発者とお繋ぎします。」</p></blockquote><hr><h2 id="_3-障害要素の要約および対応計画の策定-2分" tabindex="-1">3. 障害要素の要約および対応計画の策定（2分） <a class="header-anchor" href="#_3-障害要素の要約および対応計画の策定-2分" aria-label="Permalink to “3. 障害要素の要約および対応計画の策定（2分）”">​</a></h2><p><strong>スクラムマスター</strong>:</p><blockquote><p>「ここまで共有された障害要素を整理すると、以下の3点になります。</p><ol><li>デザイン・開発間の調整ミーティングが必要</li><li>テストサーバーの CPU 使用率に関する問題</li><li>QA テストシナリオの確認が必要</li></ol><p>これら3つの項目については、私から各担当者と調整を進めます。」</p></blockquote><hr><h2 id="_4-会議の終了-1分" tabindex="-1">4. 会議の終了（1分） <a class="header-anchor" href="#_4-会議の終了-1分" aria-label="Permalink to “4. 会議の終了（1分）”">​</a></h2><p><strong>スクラムマスター</strong>:</p><blockquote><p>「皆さん、今日やるべきことが明確になり、障害要素も把握できました。本日の会議はここで終了し、個別の相談が必要な方はこのまま議論を続けてください。本日もよろしくお願いします。」</p></blockquote><hr><h2 id="デイリースクラムを効果的に運用するヒント" tabindex="-1">デイリースクラムを効果的に運用するヒント <a class="header-anchor" href="#デイリースクラムを効果的に運用するヒント" aria-label="Permalink to “デイリースクラムを効果的に運用するヒント”">​</a></h2><ul><li><strong>時間厳守</strong>: 15分ルールを守るため、立ったまま会議を行うことを推奨します。</li><li><strong>問題解決会議の禁止</strong>: 深い議論は別途時間を確保して実施します。</li><li><strong>全メンバーの参加</strong>: 全員が偏りなく発言できる雰囲気をつくります。</li><li><strong>視覚的補助ツールの活用</strong>: カンバンボードやタスク管理ツールなどを併用します。</li><li><strong>障害要素への集中</strong>: 問題解決に向けたアクションプランを必ず策定します。</li></ul><hr><h2 id="記録例" tabindex="-1">記録例 <a class="header-anchor" href="#記録例" aria-label="Permalink to “記録例”">​</a></h2><table tabindex="0"><thead><tr><th>担当者</th><th>昨日やったこと</th><th>今日やること</th><th>障害要素</th></tr></thead><tbody><tr><td>佐藤（開発）</td><td>ログイン API 開発完了</td><td>プロフィール取得機能の実装</td><td>なし</td></tr><tr><td>鈴木（デザイン）</td><td>決済ページ UI 完了</td><td>管理画面デザイン着手</td><td>開発チームとの調整が必要</td></tr><tr><td>高橋（バックエンド）</td><td>DB 最適化作業</td><td>パフォーマンステスト実施</td><td>テストサーバー CPU 使用率の問題</td></tr><tr><td>田中（QA）</td><td>ログイン機能テスト完了</td><td>決済機能テスト開始</td><td>テストシナリオの確認が必要</td></tr></tbody></table><hr><h1 id="デイリースクラム進行用チェックリスト" tabindex="-1">デイリースクラム進行用チェックリスト <a class="header-anchor" href="#デイリースクラム進行用チェックリスト" aria-label="Permalink to “デイリースクラム進行用チェックリスト”">​</a></h1><h2 id="ファシリテーター-スクラムマスター-チェックリスト" tabindex="-1">ファシリテーター（スクラムマスター）チェックリスト <a class="header-anchor" href="#ファシリテーター-スクラムマスター-チェックリスト" aria-label="Permalink to “ファシリテーター（スクラムマスター）チェックリスト”">​</a></h2><ul><li>[ ] 毎日同じ時間・場所（またはオンライン）で開始できたか？</li><li>[ ] 15分以内に終える準備ができているか？</li><li>[ ] 各メンバーが <strong>昨日・今日・障害</strong> の3項目のみを共有するよう促したか？</li><li>[ ] 共有された <strong>障害（Blocking Issue）</strong> を別途フォローアップ項目として記録したか？</li><li>[ ] スクラム終了後、課題解決のための追加ミーティングが必要な関係者のみを招集したか？</li></ul><hr><h2 id="チームメンバー個別共有チェックリスト" tabindex="-1">チームメンバー個別共有チェックリスト <a class="header-anchor" href="#チームメンバー個別共有チェックリスト" aria-label="Permalink to “チームメンバー個別共有チェックリスト”">​</a></h2><ul><li>[ ] 昨日自分が完了した作業は何か？</li><li>[ ] 今日自分が行う作業は何か？</li><li>[ ] 進行を妨げている障害はあるか？</li></ul><p>共有は <strong>短く明確に（1〜2文程度）</strong> 行います。 問題解決の議論は、スクラム終了後に別途実施します。</p><hr><h2 id="チームメンバー共有テンプレート例" tabindex="-1">チームメンバー共有テンプレート例 <a class="header-anchor" href="#チームメンバー共有テンプレート例" aria-label="Permalink to “チームメンバー共有テンプレート例”">​</a></h2><div class="language-text"><button title="コードをコピー" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[氏名]</span></span>
<span class="line"><span>- 昨日:</span></span>
<span class="line"><span>- 今日:</span></span>
<span class="line"><span>- 障害:</span></span></code></pre></div><hr><h2 id="チーム全体のスクラムボード例-ホワイトボード-オンライン協業ツール" tabindex="-1">チーム全体のスクラムボード例（ホワイトボード / オンライン協業ツール） <a class="header-anchor" href="#チーム全体のスクラムボード例-ホワイトボード-オンライン協業ツール" aria-label="Permalink to “チーム全体のスクラムボード例（ホワイトボード / オンライン協業ツール）”">​</a></h2><table tabindex="0"><thead><tr><th>氏名</th><th>昨日やったこと</th><th>今日やること</th><th>障害（Blocking Issue）</th></tr></thead><tbody><tr><td>太郎</td><td>ログイン API のリファクタリング完了</td><td>Google ソーシャルログイン連携の開始</td><td>Google OAuth ドキュメントへアクセス不可</td></tr><tr><td>花子</td><td>会員登録機能のテストケース作成および一部実行</td><td>会員登録機能の全体テストおよびバグ報告</td><td>テストサーバーが頻繁に切断される</td></tr><tr><td>健太</td><td>ダッシュボード UI 作業</td><td>チャートライブラリの適用および API 連携</td><td>最新版の API 仕様書が未共有</td></tr></tbody></table><hr><p>このように運用することで、チームメンバーは毎日 <strong>チェックリストに沿って発言するだけ</strong> で済み、スクラムマスターは <strong>テーブルを更新するだけ</strong> で記録と共有を同時に完結できます。</p><hr>`,64)])])}const m=a(i,[["render",o]]);export{g as __pageData,m as default};
